SELECT ID, DISCOUNT_ID, TARGET_TYPE, TARGET_ID
FROM DISCOUNT_TARGET_TB
WHERE TARGET_TYPE = 'CATEGORY' AND TARGET_ID = #{i}

SELECT ID, DISCOUNT_ID, TARGET_TYPE, TARGET_ID
FROM DISCOUNT_TARGET_TB
WHERE TARGET_TYPE = 'PRODUCT' AND TARGET_ID = #{productNumber}

SELECT ID, ONSALE_YN, NAME, TYPE, START_DATE, END_DATE, DISCOUNT_TYPE, DISCOUNT_VALUE, MAX_DISCOUNT, DESCRIPTION, MIN_PRICE
FROM DISCOUNT_TB
WHERE ID = #{discountId}
